<script setup lang="ts">
type Prize = { id: string; place: number; username: string; amount: number; claimedAt: string | null; mine: boolean }
type Draw = { id: string; seasonNumber: number; pot: number; createdAt: string; prizes: Prize[] }
const auth = useAccountAuth()
const { data: economy, countdown } = useMiniGameLobby()
const history = ref<Draw[]>([])
const loading = ref(true)
const claiming = ref<string | null>(null)
const message = ref('')
async function loadHistory() { try { history.value = (await $fetch<{ history: Draw[] }>('/api/minigames/jackpot', { retry: 0 })).history } catch {} finally { loading.value = false } }
async function claim(prize: Prize) { claiming.value = prize.id; message.value = ''; try { await $fetch('/api/minigames/claim', { method: 'POST', body: { prizeId: prize.id } }); prize.claimedAt = new Date().toISOString(); await auth.loadMe(); message.value = 'Приз зачислен на баланс.' } catch (error: any) { message.value = error?.data?.statusMessage || 'Не удалось забрать приз.' } finally { claiming.value = null } }
onMounted(() => { void auth.loadMe().catch(() => {}); void loadHistory() })
</script>
<template>
  <main class="jackpot-page"><NuxtLink class="arcade-back" to="/minigames">← Все мини-игры</NuxtLink>
    <header class="jackpot-hero"><div><p class="arcade-eyebrow">SEASON JACKPOT · LIVE</p><h1>Три места.<br><span>Один большой финал.</span></h1><p>Все проигрыши в мини-играх складываются в общий призовой фонд. Участники выбираются по весу проигрышей за сезон.</p></div><div class="hero-crown">♛<small>50 / 30 / 20</small></div></header>
    <section class="pot-panel"><div><p class="arcade-eyebrow">ДЖЕКПОТ СЕЗОНА {{ economy?.season?.number ?? '—' }}</p><strong>{{ (economy?.jackpot || 0).toLocaleString('ru-RU') }}</strong><span>фишек</span><small>До перехода сезона · {{ countdown }}</small></div><div class="pot-ring"><i/><b>LIVE</b></div></section>
    <section class="rules"><div><b>01</b><span>Играй в Rocket или Mines</span></div><div><b>02</b><span>Проигрыши увеличивают шанс</span></div><div><b>03</b><span>Три приза выдаются после перехода</span></div></section>
    <section class="participants arcade-panel"><div class="panel-heading"><div><p class="arcade-eyebrow">ТЕКУЩИЙ РОЗЫГРЫШ</p><h2>Кто участвует</h2></div><span>{{ economy?.participants?.length || 0 }} игроков</span></div><div v-if="!economy?.participants?.length" class="arcade-empty">Сделайте первую игру, чтобы попасть в список участников.</div><div v-for="(item,index) in economy?.participants" :key="item.userId" class="participant-row"><span class="rank">{{ String(index+1).padStart(2,'0') }}</span><span class="participant-name"><b>{{ item.username }}</b><small>{{ item.games }} игр · проиграно {{ item.lost.toLocaleString('ru-RU') }}</small></span><span class="chance">{{ item.chance.toFixed(2) }}%</span><div class="chance-bar"><i :style="{width:item.chance+'%'}"/></div></div></section>
    <section class="history arcade-panel"><div class="panel-heading"><div><p class="arcade-eyebrow">АРХИВ</p><h2>Прошлые джекпоты</h2></div><span>Сезоны 1+</span></div><div v-if="loading" class="arcade-empty">Загружаем историю…</div><div v-else-if="!history.length" class="arcade-empty">Первый розыгрыш появится после завершения сезона 1.</div><article v-for="draw in history" :key="draw.id" class="draw"><div class="draw-head"><strong>Сезон {{ draw.seasonNumber }}</strong><span>{{ draw.pot.toLocaleString('ru-RU') }} фишек</span></div><div class="prizes"><div v-for="prize in draw.prizes" :key="prize.id" class="prize" :class="`place-${prize.place}`"><b>{{ prize.place }}</b><span>{{ prize.username }}</span><strong>{{ prize.amount.toLocaleString('ru-RU') }}</strong><button v-if="prize.mine && !prize.claimedAt" class="arcade-button" :disabled="claiming===prize.id" @click="claim(prize)">{{ claiming===prize.id ? '...' : 'Забрать' }}</button><em v-else-if="prize.mine">Получено</em></div></div></article></section><p v-if="message" class="claim-message">{{ message }}</p>
  </main>
</template>
